-- Disposable native PostgreSQL 17 platform scaffolding, never application authorization stubs.
-- No pg_net, HTTP, Vault encryption or cron worker is installed; all external dispatch fails closed.
CREATE SCHEMA auth;
CREATE SCHEMA extensions;
CREATE SCHEMA storage;
CREATE SCHEMA vault;
CREATE SCHEMA net;
CREATE SCHEMA cron;
CREATE PUBLICATION supabase_realtime;
CREATE TABLE auth.users(id uuid primary key, email text, raw_app_meta_data jsonb default '{}', raw_user_meta_data jsonb default '{}', created_at timestamptz default now(), updated_at timestamptz default now(), last_sign_in_at timestamptz, encrypted_password text, email_confirmed_at timestamptz, phone text, aud text, role text);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$select coalesce(nullif(current_setting('request.jwt.claim.sub',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid$$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$select coalesce(nullif(current_setting('request.jwt.claims',true),'')::jsonb,'{}'::jsonb)$$;
CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$select coalesce(nullif(current_setting('request.jwt.claim.role',true),''),auth.jwt()->>'role')$$;
CREATE FUNCTION auth.email() RETURNS text LANGUAGE sql STABLE AS $$select auth.jwt()->>'email'$$;
CREATE TABLE storage.buckets(id text primary key,name text,public boolean default false,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,owner uuid,owner_id text,metadata jsonb);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION storage.foldername(name text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$select (string_to_array(name,'/'))[1:array_length(string_to_array(name,'/'),1)-1]$$;
CREATE TABLE vault.secrets(id uuid primary key default gen_random_uuid(),name text,secret text,description text);
CREATE VIEW vault.decrypted_secrets AS SELECT id,name,secret as decrypted_secret,description FROM vault.secrets;
CREATE FUNCTION net.http_post(url text,body jsonb default '{}'::jsonb,params jsonb default '{}'::jsonb,headers jsonb default '{}'::jsonb,timeout_milliseconds integer default 1000) RETURNS bigint LANGUAGE plpgsql AS $$begin raise exception 'ISOLATED_EXTERNAL_TRANSPORT_DISABLED';end$$;
CREATE TABLE cron.job(jobid bigint generated by default as identity primary key,jobname text unique,schedule text,command text,active boolean default true,username text default 'postgres');
CREATE FUNCTION cron.schedule(job_name text,schedule text,command text) RETURNS bigint LANGUAGE plpgsql AS $$declare result bigint;begin insert into cron.job(jobname,schedule,command,active) values(job_name,schedule,command,true) on conflict(jobname) do update set schedule=excluded.schedule,command=excluded.command returning jobid into result;return result;end$$;
CREATE FUNCTION cron.unschedule(job_name text) RETURNS boolean LANGUAGE plpgsql AS $$begin delete from cron.job where jobname=job_name;return found;end$$;
CREATE FUNCTION cron.unschedule(job_id bigint) RETURNS boolean LANGUAGE plpgsql AS $$begin delete from cron.job where jobid=job_id;return found;end$$;
GRANT USAGE ON SCHEMA public,auth,extensions,storage TO anon,authenticated,service_role;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA auth TO anon,authenticated,service_role;
GRANT ALL ON ALL TABLES IN SCHEMA storage TO anon,authenticated,service_role;
GRANT SELECT ON auth.users TO supabase_auth_admin;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON TABLES TO anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON SEQUENCES TO anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON FUNCTIONS TO anon,authenticated,service_role;

CREATE FUNCTION cron.alter_job(job_id bigint,schedule text DEFAULT NULL,command text DEFAULT NULL,database text DEFAULT NULL,username text DEFAULT NULL,active boolean DEFAULT NULL) RETURNS void LANGUAGE plpgsql AS $$begin update cron.job j set schedule=coalesce(alter_job.schedule,j.schedule),command=coalesce(alter_job.command,j.command),username=coalesce(alter_job.username,j.username),active=coalesce(alter_job.active,j.active) where j.jobid=job_id;end$$;
